-- Datos sintéticos de métricas — octubre 2026
--
-- Alcance:
--   * Hospital 1 (Güemes Hospital) y especialidad 1 (CLINICA_MEDICA).
--   * Sector 1, sala 1 y gestor de cola 1 del initial-data.sql.
--   * Médico demo MTR-DEMO-001 y una sesión diaria del 01/10 al 31/10.
--   * Todos los ingresos son históricos: no dejan pacientes en la cola viva.
--   * Atendidos: entrada y consulta FINALIZADA + atención FINALIZADA.
--   * No atendidos: entrada y consulta CANCELADA, sin atención médica.
--   * El chat solo se crea para los casos con pretriage realizado.
--
-- Requisitos de la instancia:
--   * JPA_DDL_AUTO=update (con create-drop los datos se pierden al reiniciar).
--   * Membresía ADMIN_HOSPITAL activa para el hospital 1. Este script no la crea;
--     sin ella, GET /api/admin/hospitales/1/metricas responde 403.
--
-- ADVERTENCIA: ejecutar una sola vez sobre una base recién inicializada
-- con initial-data.sql. Las tablas medico, asignacion_medico_hospital,
-- sesion_atencion_medica, paciente, chat, consulta_medica, entrada_cola
-- y atencion_medica deben estar vacías. El bloque DO siguiente lo
-- verifica y aborta la transacción si algo no cumple.
--
-- Resumen esperado:
--   ingresos a cola: 692
--   atendidos: 621
--   no atendidos: 71
--   con pretriage: 555
--   sin pretriage: 137
--   espera promedio: 37.9 minutos
--   distribución bot:
--     RIESGO_VITAL_INMEDIATO: 20
--     MUY_URGENTE: 63
--     URGENTE: 206
--     NORMAL: 309
--     NO_URGENTE: 94
--   distribución médica:
--     RIESGO_VITAL_INMEDIATO: 17
--     MUY_URGENTE: 63
--     URGENTE: 177
--     NORMAL: 267
--     NO_URGENTE: 97
--     SIN_REVISION: 71

BEGIN;

-- El archivo está en UTF-8 (nombres y JSON con acentos).
SET LOCAL client_encoding = 'UTF8';

-- Preflight: datos base presentes y tablas de destino vacías.
-- Los IDs implícitos 1..N requieren secuencias sin usar.
DO $$
DECLARE
    tabla text;
    filas bigint;
    secuencia text;
    ultimo bigint;
    usada boolean;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM hospital WHERE id = 1) THEN
        RAISE EXCEPTION 'Falta el hospital 1. Ejecutá initial-data.sql primero.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM especialidad_medica WHERE id = 1 AND codigo = 'CLINICA_MEDICA') THEN
        RAISE EXCEPTION 'La especialidad 1 no es CLINICA_MEDICA. Revisá initial-data.sql y el seeder de especialidades.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM sector WHERE id = 1 AND id_hospital = 1 AND id_especialidad = 1) THEN
        RAISE EXCEPTION 'Falta el sector 1 del hospital 1 / CLINICA_MEDICA.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM sala WHERE id = 1 AND id_hospital = 1 AND id_especialidad_medica = 1 AND id_sector = 1) THEN
        RAISE EXCEPTION 'Falta la sala 1 del sector 1.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM gestor_de_cola WHERE id = 1 AND id_hospital = 1 AND id_especialidad_medica = 1 AND id_sector = 1) THEN
        RAISE EXCEPTION 'Falta el gestor de cola 1 del hospital 1 / CLINICA_MEDICA.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM hospital_especialidad_medica WHERE id_hospital = 1 AND id_especialidad_medica = 1) THEN
        RAISE EXCEPTION 'El hospital 1 no tiene habilitada la especialidad CLINICA_MEDICA.';
    END IF;

    FOREACH tabla IN ARRAY ARRAY[
        'medico', 'asignacion_medico_hospital', 'sesion_atencion_medica',
        'paciente', 'chat', 'consulta_medica', 'entrada_cola', 'atencion_medica'
    ] LOOP
        EXECUTE format('SELECT count(*) FROM %I', tabla) INTO filas;
        IF filas > 0 THEN
            RAISE EXCEPTION 'La tabla % no está vacía (% filas). Ejecutá este script sobre una base recién inicializada.', tabla, filas;
        END IF;
        secuencia := pg_get_serial_sequence(tabla, 'id');
        IF secuencia IS NOT NULL THEN
            EXECUTE format('SELECT last_value, is_called FROM %s', secuencia) INTO ultimo, usada;
            IF ultimo <> 1 OR usada THEN
                RAISE EXCEPTION 'La secuencia de % no empezaría en 1 (last_value=%, is_called=%). Reiniciá las secuencias o recreá la base.', tabla, ultimo, usada;
            END IF;
        END IF;
    END LOOP;
END $$;

